1. **Create a new script** named `FirstPersonController.gd` and attach it to a `KinematicBody` node.
2. **Define the script**:
```gdscript
extends KinematicBody

var speed = 5.0
var sensitivity = 0.1

func _ready():
    input_map = {
        "move_forward": InputEventKey.KEY_W,
        "move_backward": InputEventKey.KEY_S,
        "move_left": InputEventKey.KEY_A,
        "move_right": InputEventKey.KEY_D,
        "look_up": InputEventKey.KEY_SPACE,
        "look_down": InputEventKey.KEY_LEFT_SHIFT
    }

func _process(delta):
    var move_vec = Vector3()
    if Input.is_action_pressed(input_map["move_forward"]):
        move_vec.z += 1
    if Input.is_action_pressed(input_map["move_backward"]):
        move_vec.z -= 1
    if Input.is_action_pressed(input_map["move_left"]):
        move_vec.x -= 1
    if Input.is_action_pressed(input_map["move_right"]):
        move_vec.x += 1

    move_vec = move_vec.normalized() * speed * delta
    velocity = move_vec

    var look_vec = Vector3()
    if Input.is_action_pressed(input_map["look_up"]):
        look_vec.y += 1
    if Input.is_action_pressed(input_map["look_down"]):
        look_vec.y -= 1

    look_vec = look_vec.normalized() * sensitivity * delta
    rotation_y += look_vec.x
    rotation
